#include <stdio.h>
static int sum(const int *values, size_t count) { int result=0; for(size_t i=0;i<count;++i) result+=values[i]; return result; }
int main(void) {
    int data[20]; size_t n;
    if(scanf("%zu", &n)!=1 || n>20) return 1;
    for(size_t i=0;i<n;++i) if(scanf("%d", &data[i])!=1) return 1;
    printf("%d\n", sum(data,n));
    return 0;
}
